const W = 800;
const H = 800;
const PAD = 24;

/* ---------------- projection: Mercator, by hand ---------------- */
/* d3.geoContains works on spherical geometry and flips when ring winding
   is wrong, which Natural Earth does not guarantee. Brazil crosses no
   antimeridian, so planar point-in-polygon in lon/lat is exact and safe. */

const D2R = Math.PI / 180;

function mercRaw(lon, lat) {
  const l = Math.max(-85, Math.min(85, lat));
  return [lon * D2R, Math.log(Math.tan(Math.PI / 4 + (l * D2R) / 2))];
}

const FIT = (() => {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const s of STATES_RAW)
    for (const poly of s.polys)
      for (const ring of poly)
        for (const [lon, lat] of ring) {
          const [x, y] = mercRaw(lon, lat);
          if (x < x0) x0 = x;
          if (x > x1) x1 = x;
          if (y < y0) y0 = y;
          if (y > y1) y1 = y;
        }
  const k = Math.min((W - 2 * PAD) / (x1 - x0), (H - 2 * PAD) / (y1 - y0));
  return { k, tx: (W - k * (x0 + x1)) / 2, ty: (H + k * (y0 + y1)) / 2 };
})();

function project(lon, lat) {
  const [x, y] = mercRaw(lon, lat);
  return [FIT.k * x + FIT.tx, FIT.ty - FIT.k * y];
}

function invert(px, py) {
  const x = (px - FIT.tx) / FIT.k;
  const y = (FIT.ty - py) / FIT.k;
  return [(x * 180) / Math.PI, ((2 * Math.atan(Math.exp(y)) - Math.PI / 2) * 180) / Math.PI];
}

/* ---------------- geometry helpers ---------------- */

function ringContains(ring, lon, lat) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

/* Even-odd across every ring of every piece, so a state's interior rings
   (there are none in this dataset, but multi-piece states like Pará and
   Bahia do exist) never fall through the cracks. */
function polysContain(polys, lon, lat) {
  for (const poly of polys) {
    let hits = 0;
    for (const ring of poly) if (ringContains(ring, lon, lat)) hits++;
    if (hits % 2 === 1) return true;
  }
  return false;
}

function ringArea(ring) {
  let a = 0;
  for (let i = 0; i < ring.length; i++) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[(i + 1) % ring.length];
    a += x1 * y2 - x2 * y1;
  }
  return Math.abs(a) / 2;
}

function polysToPath(polys) {
  let d = "";
  for (const poly of polys)
    for (const ring of poly) {
      for (let i = 0; i < ring.length; i++) {
        const [x, y] = project(ring[i][0], ring[i][1]);
        d += (i ? "L" : "M") + x.toFixed(2) + " " + y.toFixed(2);
      }
      d += "Z";
    }
  return d;
}

function kmBetween(lon1, lat1, lon2, lat2) {
  const R = 6371, t = Math.PI / 180;
  const dLat = (lat2 - lat1) * t, dLon = (lon2 - lon1) * t;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * t) * Math.cos(lat2 * t) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

/* ---------------- derived once at module load: states ---------------- */

const STATE_PATHS = {};
const MARKERS = {};   // interior point, for tiny-state locator rings
const BBOX = {};
const VERTS = {};      // projected outline vertices, for near-miss/gap fallback
const AREA = {};

for (const s of STATES_RAW) {
  STATE_PATHS[s.id] = polysToPath(s.polys);

  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  const pts = [];
  for (const poly of s.polys)
    for (const ring of poly)
      for (const [lon, lat] of ring) {
        const p = project(lon, lat);
        pts.push(p);
        if (p[0] < x0) x0 = p[0];
        if (p[0] > x1) x1 = p[0];
        if (p[1] < y0) y0 = p[1];
        if (p[1] > y1) y1 = p[1];
      }
  BBOX[s.id] = [x0, y0, x1, y1];
  VERTS[s.id] = pts;

  const big = s.polys.slice().sort((a, b) => ringArea(b[0]) - ringArea(a[0]))[0][0];
  let cx = 0, cy = 0;
  for (const [lon, lat] of big) { cx += lon; cy += lat; }
  cx /= big.length; cy /= big.length;
  if (!polysContain(s.polys, cx, cy)) {
    let bx = Infinity, by = Infinity, bX = -Infinity, bY = -Infinity;
    for (const [lon, lat] of big) {
      if (lon < bx) bx = lon; if (lon > bX) bX = lon;
      if (lat < by) by = lat; if (lat > bY) bY = lat;
    }
    let best = null, bestD = -1;
    for (let i = 1; i < 13; i++)
      for (let j = 1; j < 13; j++) {
        const lon = bx + ((bX - bx) * i) / 13;
        const lat = by + ((bY - by) * j) / 13;
        if (!polysContain(s.polys, lon, lat)) continue;
        const d = Math.min(lon - bx, bX - lon, lat - by, bY - lat);
        if (d > bestD) { bestD = d; best = [lon, lat]; }
      }
    if (best) { cx = best[0]; cy = best[1]; }
  }
  MARKERS[s.id] = project(cx, cy);

  let a = 0;
  for (const poly of s.polys) {
    const r = poly[0].map(([lon, lat]) => project(lon, lat));
    let ra = 0;
    for (let i = 0; i < r.length; i++) {
      const p = r[i], q = r[(i + 1) % r.length];
      ra += p[0] * q[1] - q[0] * p[1];
    }
    a += Math.abs(ra) / 2;
  }
  AREA[s.id] = a;
}

const BORDER_PATH = STATES_RAW.map((s) => STATE_PATHS[s.id]).join("");
const DRAW_ORDER = STATES_RAW.slice().sort((a, b) => AREA[b.id] - AREA[a.id]);
const STATE_BY_ID = Object.fromEntries(STATES_RAW.map((s) => [s.id, s]));

/* Small on the map at default zoom -- projected area under sqrt(40) units.
   A bounding-box test alone misreads long thin states (Sergipe, Alagoas) as
   roomy when there's nowhere in them to land a finger; area does not. */
const STATE_SMALL = new Set(
  STATES_RAW.filter((s) => Math.sqrt(AREA[s.id]) < 40).map((s) => s.id)
);

/* ---------------- derived once at module load: elevation ---------------- */

const ELEV_PATHS = ELEV_BANDS_RAW.map((b) => ({
  d: polysToPath(b.polys),
  color: b.color,
}));

/* ---------------- answer matching ---------------- */

function normalize(str) {
  return str
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z]+/g, " ")
    .trim();
}

// One substitution or one adjacent transposition is forgiven on longer
// names -- Brazilian place names are long, and the point is recall, not
// exact orthography ("Amazonia" for Amazonas, "Cuiba" for Cuiabá).
function within1(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  if (a.length === b.length) {
    const diff = [];
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) diff.push(i);
    if (diff.length === 1) return true;
    return diff.length === 2 && diff[1] === diff[0] + 1 && a[diff[0]] === b[diff[1]] && a[diff[1]] === b[diff[0]];
  }
  const s = a.length < b.length ? a : b, l = a.length < b.length ? b : a;
  let i = 0, j = 0, skipped = false;
  while (i < s.length && j < l.length) {
    if (s[i] === l[j]) { i++; j++; continue; }
    if (skipped) return false;
    skipped = true; j++;
  }
  return true;
}

function matches(accepted, text) {
  const t = normalize(text);
  if (!t) return false;
  for (const a of accepted) if (a === t || (a.length >= 6 && within1(a, t))) return true;
  return false;
}

// States: identified by full name, official two-letter code, or an alias.
const STATE_ACCEPTED = {};
for (const s of STATES_RAW) {
  const set = new Set([normalize(s.name), normalize(s.abbr), ...s.aliases.map(normalize)]);
  set.delete("");
  STATE_ACCEPTED[s.id] = set;
}

const STATE_POOL = STATES_RAW.map((s) => ({
  ...s,
  x: MARKERS[s.id][0],
  y: MARKERS[s.id][1],
  role: s.id === "BR-DF" ? "Federal District" : "State",
  accepted: STATE_ACCEPTED[s.id],
}));

// Cities: identified by name or alias only. Deliberately NOT by the state's
// two-letter code -- that code lives on c.abbr for display, but two cities
// share a state (Vitória/Serra, Florianópolis/Joinville), so treating it as
// an accepted answer would let one code identify two different targets.
const CITIES = CITIES_RAW.map((c) => {
  const [x, y] = project(c.lon, c.lat);
  const set = new Set([normalize(c.n), ...(c.aliases || []).map(normalize)]);
  set.delete("");
  return { ...c, x, y, accepted: set };
});

/* ---------------- city pools, scope, population tiers ---------------- */

const SCOPES = {
  all: { label: "All", filter: () => true },
  admin: { label: "Capitals", filter: (c) => c.admin },
  econ: { label: "Commercial", filter: (c) => c.econ },
};

const SCOPE_BLURB = {
  all: "every state capital, plus the commercial hub where it differs",
  admin: "one per state — the seat of government",
  econ: "one per state — where the money is",
};

const POOLS = Object.fromEntries(Object.entries(SCOPES).map(([k, s]) => [k, CITIES.filter(s.filter)]));

function parsePop(pop) {
  const m = /^~?([\d.]+)([KM])$/.exec(pop);
  if (!m) return 0;
  return parseFloat(m[1]) * (m[2] === "M" ? 1e6 : 1e3);
}

const POP_TIERS = {
  third: { label: "Top ⅓", frac: 1 / 3 },
  twoThirds: { label: "Top ⅔", frac: 2 / 3 },
  all: { label: "All sizes", frac: 1 },
};

function topByPopulation(pool, frac) {
  if (frac >= 1) return pool;
  const ranked = [...pool].sort((a, b) => parsePop(b.pop) - parsePop(a.pop));
  return ranked.slice(0, Math.max(1, Math.ceil(ranked.length * frac)));
}

// Per-city tap allowance in km: half the distance to the nearest other city
// in the same scope, floored at 150 km and capped at 500 km. A single fixed
// number can't serve both a cluster (Vitória/Serra, 21 km apart) and an
// isolated capital (Boa Vista, 665 km from its nearest neighbour) -- the
// floor means no city is ever tighter than 150 km regardless of how crowded
// its corner of the map gets.
const GEO_TOL_MIN_KM = 150;
const GEO_TOL_MAX_KM = 500;

function toleranceFor(pool, city) {
  let nearest = Infinity;
  for (const o of pool) {
    if (o === city) continue;
    const d = kmBetween(city.lon, city.lat, o.lon, o.lat);
    if (d < nearest) nearest = d;
  }
  return clamp(nearest / 2, GEO_TOL_MIN_KM, GEO_TOL_MAX_KM);
}

// Keyed by scope, then by city id -- e.g. TOLERANCES.admin["belem-pa"].
const TOLERANCES = Object.fromEntries(
  Object.entries(POOLS).map(([k, pool]) => [k, Object.fromEntries(pool.map((c) => [c.id, toleranceFor(pool, c)]))])
);

/* ---------------- tap resolution ---------------- */

// A city tap is right if it lands within the target's own allowance --
// full stop. Distance to the target is the whole rule; the number the
// tolerance promises is the number a tap actually gets.
function resolveCityTap(tol, lon, lat, target) {
  const km = kmBetween(lon, lat, target.lon, target.lat);
  return { correct: km <= tol, km };
}

// A state tap is right if it lands inside the target's own outline -- a
// shape, not a point. Three layers, tried in order:
//   1. A real polygon hit, on the target or a neighbour.
//   2. Nothing hit: an open-water rescue for small states, since Sergipe or
//      the Federal District can be only a few pixels wide at default zoom.
//   3. Still nothing (a simplification gap between two ordinary-sized
//      neighbours): credit whichever state's outline is physically closest.
function resolveStateTap(lon, lat, x, y, zoomK, target) {
  for (const s of STATES_RAW) {
    if (polysContain(s.polys, lon, lat)) return { correct: s.id === target.id, guessId: s.id };
  }

  const tol = 36 / zoomK;
  let bestId = null, bestD = tol;
  for (const id of STATE_SMALL) {
    let d = Infinity;
    for (const [vx, vy] of VERTS[id]) {
      const dd = Math.hypot(vx - x, vy - y);
      if (dd < d) d = dd;
    }
    if (d <= bestD) { bestD = d; bestId = id; }
  }
  if (bestId) return { correct: bestId === target.id, guessId: bestId };

  let nb = null, nbD = Infinity;
  for (const s of STATES_RAW) {
    for (const [vx, vy] of VERTS[s.id]) {
      const dd = Math.hypot(vx - x, vy - y);
      if (dd < nbD) { nbD = dd; nb = s.id; }
    }
  }
  return { correct: nb === target.id, guessId: nb };
}

/* ---------------- the journey: Oiapoque to Chuí ---------------- */
/* "De Oiapoque a Chuí" -- Brazil's own shorthand for one end of the country
   to the other, roughly 4,400 km by road along the old north-south trunk
   corridor. The endpoints are narrative bookends, not quiz targets. */

const TOTAL_KM = 4400;

const CITY_LEGS = [
  { at: 0.0, name: "Oiapoque" },
  { at: 0.06, name: "Macapá" },
  { at: 0.16, name: "Belém" },
  { at: 0.3, name: "Palmas" },
  { at: 0.42, name: "Brasília" },
  { at: 0.55, name: "Belo Horizonte" },
  { at: 0.68, name: "São Paulo" },
  { at: 0.77, name: "Curitiba" },
  { at: 0.85, name: "Florianópolis" },
  { at: 0.93, name: "Porto Alegre" },
  { at: 1.0, name: "Chuí" },
];

const STATE_LEGS = [
  { at: 0.0, name: "Amapá" },
  { at: 0.06, name: "Amapá" },
  { at: 0.16, name: "Pará" },
  { at: 0.3, name: "Tocantins" },
  { at: 0.42, name: "Distrito Federal" },
  { at: 0.55, name: "Minas Gerais" },
  { at: 0.68, name: "São Paulo" },
  { at: 0.77, name: "Paraná" },
  { at: 0.85, name: "Santa Catarina" },
  { at: 0.93, name: "Rio Grande do Sul" },
  { at: 1.0, name: "Rio Grande do Sul" },
];

const JOURNEY_LABEL = {
  cities: `${CITY_LEGS[0].name} to ${CITY_LEGS[CITY_LEGS.length - 1].name}`,
  states: `${STATE_LEGS[0].name} to ${STATE_LEGS[STATE_LEGS.length - 1].name}`,
};

function legFor(frac, legs) {
  let l = legs[0];
  for (const leg of legs) if (frac >= leg.at) l = leg;
  return l.name;
}

function shuffled(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/* ---------------- gestures: pinch/drag to zoom and pan, click to tap ---------------- */

function useMapGestures(onTapLonLat) {
  const [view, setView] = useState({ k: 1, tx: 0, ty: 0 });
  const svgRef = useRef(null);
  const gRef = useRef(null);
  const gesture = useRef(null);
  const lastTouchTap = useRef(0);

  const toLocal = useCallback((clientX, clientY, el) => {
    if (!svgRef.current || !el) return null;
    const pt = svgRef.current.createSVGPoint();
    pt.x = clientX;
    pt.y = clientY;
    const ctm = el.getScreenCTM();
    return ctm ? pt.matrixTransform(ctm.inverse()) : null;
  }, []);

  const handleTap = useCallback(
    (clientX, clientY) => {
      const p = toLocal(clientX, clientY, gRef.current);
      if (!p) return;
      const [lon, lat] = invert(p.x, p.y);
      onTapLonLat(lon, lat, { x: p.x, y: p.y }, view.k);
    },
    [toLocal, onTapLonLat, view.k]
  );

  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;
    const mid = (a, b) => ({ x: (a.clientX + b.clientX) / 2, y: (a.clientY + b.clientY) / 2 });

    const startPinch = (t1, t2) => {
      const m = mid(t1, t2);
      gesture.current = {
        mode: "pinch",
        anchor: toLocal(m.x, m.y, gRef.current),
        startDist: Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY),
        startK: view.k,
      };
    };

    const onStart = (e) => {
      if (e.touches.length >= 2) startPinch(e.touches[0], e.touches[1]);
      else
        gesture.current = {
          mode: "tap",
          x: e.touches[0].clientX,
          y: e.touches[0].clientY,
          moved: false,
          lastLocal: toLocal(e.touches[0].clientX, e.touches[0].clientY, svgRef.current),
        };
    };

    const onMove = (e) => {
      const g = gesture.current;
      if (!g) return;
      if (e.touches.length >= 2) {
        if (g.mode !== "pinch") return startPinch(e.touches[0], e.touches[1]);
        e.preventDefault();
        const [t1, t2] = [e.touches[0], e.touches[1]];
        const d = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
        const k = clamp(g.startK * (d / g.startDist), 1, 16);
        const m = mid(t1, t2);
        const p = toLocal(m.x, m.y, svgRef.current);
        if (p && g.anchor) setView({ k, tx: p.x - k * g.anchor.x, ty: p.y - k * g.anchor.y });
      } else if (g.mode === "tap") {
        const touch = e.touches[0];
        if (Math.hypot(touch.clientX - g.x, touch.clientY - g.y) > 10) g.moved = true;
        if (g.moved) {
          e.preventDefault();
          const cur = toLocal(touch.clientX, touch.clientY, svgRef.current);
          if (cur && g.lastLocal) {
            const dx = cur.x - g.lastLocal.x, dy = cur.y - g.lastLocal.y;
            setView((v) => ({ ...v, tx: v.tx + dx, ty: v.ty + dy }));
          }
          g.lastLocal = cur;
        }
      }
    };

    const onEnd = (e) => {
      const g = gesture.current;
      if (g && g.mode === "tap" && !g.moved) {
        e.preventDefault();
        lastTouchTap.current = Date.now();
        handleTap(g.x, g.y);
      }
      if (e.touches.length === 0) gesture.current = null;
    };

    el.addEventListener("touchstart", onStart, { passive: false });
    el.addEventListener("touchmove", onMove, { passive: false });
    el.addEventListener("touchend", onEnd, { passive: false });
    el.addEventListener("touchcancel", onEnd, { passive: false });
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove", onMove);
      el.removeEventListener("touchend", onEnd);
      el.removeEventListener("touchcancel", onEnd);
    };
  }, [toLocal, handleTap, view.k]);

  // Mouse equivalent for desktop: click-and-drag pans, a plain click taps.
  // Tracked on window rather than the svg so a drag keeps following the
  // cursor even if it leaves the map mid-gesture.
  const mouseDrag = useRef(null);
  const wasDragged = useRef(false);

  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;

    const onDown = (e) => {
      if (e.button !== 0) return;
      wasDragged.current = false;
      mouseDrag.current = { x: e.clientX, y: e.clientY, moved: false, lastLocal: toLocal(e.clientX, e.clientY, svgRef.current) };
    };
    const onMove = (e) => {
      const g = mouseDrag.current;
      if (!g) return;
      if (!g.moved && Math.hypot(e.clientX - g.x, e.clientY - g.y) > 4) { g.moved = true; wasDragged.current = true; }
      if (g.moved) {
        const cur = toLocal(e.clientX, e.clientY, svgRef.current);
        if (cur && g.lastLocal) {
          const dx = cur.x - g.lastLocal.x, dy = cur.y - g.lastLocal.y;
          setView((v) => ({ ...v, tx: v.tx + dx, ty: v.ty + dy }));
        }
        g.lastLocal = cur;
      }
    };
    const onUp = () => { mouseDrag.current = null; };

    el.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    return () => {
      el.removeEventListener("mousedown", onDown);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
  }, [toLocal]);

  const onClick = (e) => {
    if (wasDragged.current) { wasDragged.current = false; return; }
    if (Date.now() - lastTouchTap.current < 600) return;
    handleTap(e.clientX, e.clientY);
  };

  const onWheel = (e) => {
    e.preventDefault();
    const k = clamp(view.k * (e.deltaY < 0 ? 1.15 : 1 / 1.15), 1, 16);
    const p = toLocal(e.clientX, e.clientY, svgRef.current);
    const a = toLocal(e.clientX, e.clientY, gRef.current);
    if (p && a) setView({ k, tx: p.x - k * a.x, ty: p.y - k * a.y });
  };

  const reset = () => setView({ k: 1, tx: 0, ty: 0 });

  return { view, reset, svgRef, gRef, onClick, onWheel };
}

/* ---------------- palette ---------------- */

const C = {
  page: "#12161f", panel: "#1b212e", ocean: "#0c1219", land: "#39445a",
  amber: "#e3a542", cream: "#f3e9d8", green: "#5fbf7a", red: "#e2645a",
  border: "#7c88a3", muted: "#8b93a7",
};
const SERIF = 'Georgia, "Iowan Old Style", "Times New Roman", serif';
const MONO = 'ui-monospace, "SF Mono", Menlo, Consolas, monospace';
const SANS = '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';

/* ---------------- map pieces ---------------- */

function BaseMap({ k, elevation }) {
  const seam = { fill: C.land, stroke: C.land, strokeWidth: 1 / k, strokeLinejoin: "round" };
  return (
    <>
      <rect x={-2000} y={-2000} width={6000} height={6000} fill={C.ocean} />
      {DRAW_ORDER.map((s) => (
        <path key={s.id} d={STATE_PATHS[s.id]} fillRule="evenodd" {...seam} />
      ))}
      {elevation &&
        ELEV_PATHS.map((b, i) => (
          <path key={i} d={b.d} fillRule="evenodd" fill={b.color} stroke={b.color} strokeWidth={0.6 / k} strokeLinejoin="round" opacity={0.92} />
        ))}
    </>
  );
}

function Borders({ on, k }) {
  if (!on) return null;
  return <path d={BORDER_PATH} fill="none" stroke={C.border} strokeWidth={0.9 / k} strokeLinejoin="round" opacity={0.75} pointerEvents="none" />;
}

function StateHighlight({ id, color, k }) {
  const d = STATE_PATHS[id];
  if (!d) return null;
  return (
    <g>
      <path d={d} fillRule="evenodd" fill={color} fillOpacity={0.45} stroke={color} strokeWidth={2.2 / k} strokeLinejoin="round" opacity={0.9} />
      {STATE_SMALL.has(id) && (
        <circle cx={MARKERS[id][0]} cy={MARKERS[id][1]} r={15 / k} fill="none" stroke={color} strokeWidth={2 / k} opacity={0.95} />
      )}
    </g>
  );
}

function Compass() {
  return (
    <svg width={30} height={30} viewBox="0 0 34 34" style={S.compass} aria-hidden="true">
      <circle cx="17" cy="17" r="14" fill="none" stroke="#5a6579" strokeWidth="1" />
      <path d="M17 5 L20 17 L17 29 L14 17 Z" fill="#5a6579" />
      <circle cx="17" cy="17" r="2" fill="#0c1219" />
    </svg>
  );
}

function TapMap({ gestures, children, label }) {
  const { view, reset, svgRef, gRef, onClick, onWheel } = gestures;
  return (
    <div className="abz-map" style={S.mapWrap}>
      <svg ref={svgRef} viewBox={`0 0 ${W} ${H}`} style={{ ...S.svg, touchAction: "none" }} onClick={onClick} onWheel={onWheel} role="img" aria-label={label}>
        <rect x={0} y={0} width={W} height={H} fill={C.ocean} />
        <g ref={gRef} transform={`translate(${view.tx},${view.ty}) scale(${view.k})`}>
          {children(view.k)}
        </g>
      </svg>
      <Compass />
      {(view.k > 1.01 || Math.abs(view.tx) > 0.5 || Math.abs(view.ty) > 0.5) && (
        <button className="abz-btn" style={S.reset} onClick={reset}>Reset view</button>
      )}
    </div>
  );
}

/* ---------------- the quiz ---------------- */

// TOLERANCES is keyed by scope ("all"/"admin"/"econ"). Population-tier
// trimming narrows which cities appear, not the geometry between them, so
// the scope's tolerance table still applies to whatever is left; the pool
// passed in always came from exactly one scope, so any table with an entry
// for this target is the right one.
function poolTolerance(target) {
  for (const k of Object.keys(TOLERANCES)) if (TOLERANCES[k][target.id] !== undefined) return TOLERANCES[k][target.id];
  return GEO_TOL_MAX_KM;
}

function Quiz({ domain, pool, input, session, borders, elevation, hints }) {
  const journey = session === "journey";
  const typing = input === "type";
  const noun = domain === "states" ? "state or the Federal District" : "city";
  const legs = domain === "states" ? STATE_LEGS : CITY_LEGS;
  const journeyEnd = legs[legs.length - 1].name;
  const journeyStart = legs[0].name;

  const [queue, setQueue] = useState(() => shuffled(pool.map((c) => c.id)));
  const [solved, setSolved] = useState(() => new Set());
  const [score, setScore] = useState({ correct: 0, total: 0 });
  const [lastAnswer, setLastAnswer] = useState(null);
  const [typed, setTyped] = useState("");
  const inputRef = useRef(null);
  const answerSeq = useRef(0);

  const targetId = queue[0];
  const target = targetId ? pool.find((c) => c.id === targetId) : null;
  const arrived = journey && !target;

  useEffect(() => {
    if (typing && inputRef.current) inputRef.current.focus();
  }, [typing, targetId]);

  const advanceQueue = useCallback(
    (wasCorrect) => {
      setTyped("");
      setQueue((q) => {
        if (journey) return wasCorrect ? q.slice(1) : [...q.slice(1), q[0]];
        return q.length <= 1 ? shuffled(pool.map((c) => c.id)) : q.slice(1);
      });
    },
    [journey, pool]
  );

  const recordAnswer = useCallback(
    (correct, extra) => {
      if (!target) return;
      setScore((s) => ({ correct: s.correct + (correct ? 1 : 0), total: s.total + 1 }));
      if (correct && journey) setSolved((prev) => new Set(prev).add(target.id));
      answerSeq.current += 1;
      setLastAnswer({
        key: answerSeq.current,
        id: target.id,
        n: domain === "states" ? target.name : target.n,
        role: target.role,
        secondary: domain === "states" ? target.capital : target.state,
        pop: target.pop,
        b: target.b,
        correct,
        domain,
        ...extra,
      });
      advanceQueue(correct);
    },
    [target, journey, advanceQueue, domain]
  );

  const onTap = useCallback(
    (lon, lat, at, zoomK) => {
      if (typing || !target) return;
      if (domain === "states") {
        const r = resolveStateTap(lon, lat, at.x, at.y, zoomK, target);
        recordAnswer(r.correct, { atX: at.x, atY: at.y, guessId: r.guessId });
      } else {
        const tol = poolTolerance(target);
        const r = resolveCityTap(tol, lon, lat, target);
        recordAnswer(r.correct, { atX: at.x, atY: at.y, km: r.km });
      }
    },
    [typing, target, domain, recordAnswer]
  );

  const gestures = useMapGestures(onTap);

  const submitTyped = () => {
    if (!target || !typed.trim()) return;
    recordAnswer(matches(target.accepted, typed), { guessText: typed.trim() });
  };

  const restart = () => {
    setQueue(shuffled(pool.map((c) => c.id)));
    setSolved(new Set());
    setScore({ correct: 0, total: 0 });
    setLastAnswer(null);
    setTyped("");
    gestures.reset();
  };

  const count = solved.size;
  const frac = pool.length ? count / pool.length : 0;
  const TARGET_FILL = C.cream;
  const showLabels = (k) => k >= 2.5;

  let prompt;
  if (arrived) prompt = <span style={{ color: C.amber, fontWeight: 700 }}>{journeyEnd}. All {pool.length}.</span>;
  else if (typing) prompt = <span style={{ color: C.muted }}>Name the marked {noun}</span>;
  else prompt = <>Find <span style={{ color: C.amber, fontWeight: 700 }}>{domain === "states" ? target.name : target.n}</span></>;

  return (
    <div className="abz-layout">
      <TapMap gestures={gestures} label={arrived ? `Map of Brazil, every ${noun} found.` : "Map of Brazil."}>
        {(k) => (
          <>
            <BaseMap k={k} elevation={elevation} />

            {journey &&
              [...solved].map((id) => {
                const c = pool.find((x) => x.id === id);
                if (!c || (target && c.id === target.id)) return null;
                if (domain === "states") {
                  return (
                    <g key={id} opacity={0.8}>
                      <path d={STATE_PATHS[c.id]} fillRule="evenodd" fill={C.amber} fillOpacity={0.26} stroke={C.amber} strokeWidth={1.2 / k} strokeLinejoin="round" />
                      {STATE_SMALL.has(c.id) && <circle cx={c.x} cy={c.y} r={13 / k} fill="none" stroke={C.amber} strokeWidth={1.4 / k} opacity={0.8} />}
                    </g>
                  );
                }
                return (
                  <g key={id}>
                    <circle cx={c.x} cy={c.y} r={3.4 / k} fill={C.amber} />
                    {showLabels(k) && (
                      <text x={c.x + 6 / k} y={c.y + 3 / k} fill={C.amber} fontSize={9 / k} fontFamily={MONO} opacity={0.85}>{c.n}</text>
                    )}
                  </g>
                );
              })}

            {lastAnswer &&
              (domain === "states" ? (
                <g key={lastAnswer.key}>
                  {!lastAnswer.correct && lastAnswer.guessId && lastAnswer.guessId !== lastAnswer.id && (
                    <StateHighlight id={lastAnswer.guessId} color={C.red} k={k} />
                  )}
                  <StateHighlight id={lastAnswer.id} color={C.green} k={k} />
                </g>
              ) : (
                (() => {
                  const c = CITIES.find((x) => x.id === lastAnswer.id);
                  if (!c) return null;
                  return (
                    <g key={lastAnswer.key} opacity={0.65}>
                      {lastAnswer.atX !== undefined && (
                        <line x1={lastAnswer.atX} y1={lastAnswer.atY} x2={c.x} y2={c.y}
                          stroke={lastAnswer.correct ? C.green : C.red} strokeWidth={1.2 / k} strokeDasharray={`${3 / k} ${3 / k}`} opacity={0.8} />
                      )}
                      <circle cx={c.x} cy={c.y} r={11 / k} fill="none" stroke={C.green} strokeWidth={2 / k} />
                      <circle cx={c.x} cy={c.y} r={4 / k} fill={C.green} />
                      {lastAnswer.atX !== undefined && (
                        <circle cx={lastAnswer.atX} cy={lastAnswer.atY} r={5 / k} fill={lastAnswer.correct ? C.green : C.red} stroke={C.ocean} strokeWidth={1.6 / k} />
                      )}
                    </g>
                  );
                })()
              ))}

            {typing && target && domain === "cities" && (
              <g>
                <circle className="abz-ping" cx={target.x} cy={target.y} r={13 / k} fill="none" stroke={TARGET_FILL} strokeWidth={2 / k} />
                <circle cx={target.x} cy={target.y} r={4.2 / k} fill={TARGET_FILL} />
                <circle cx={target.x} cy={target.y} r={9 / k} fill="none" stroke={TARGET_FILL} strokeWidth={1.4 / k} opacity={0.7} />
              </g>
            )}
            {typing && target && domain === "states" && (
              <path d={STATE_PATHS[target.id]} fillRule="evenodd" fill={TARGET_FILL} stroke={TARGET_FILL} strokeWidth={1.4 / k} strokeLinejoin="round" />
            )}

            <Borders on={borders} k={k} />
          </>
        )}
      </TapMap>

      <div className="abz-side">
        {journey ? (
          <Progress count={count} total={pool.length} km={Math.round(frac * TOTAL_KM)} frac={frac} score={score} legs={legs} />
        ) : (
          <ScoreRow score={score} />
        )}

        <div style={S.prompt}>{prompt}</div>
        <div style={S.subPrompt}>
          {arrived ? "\u00a0" : hints ? (domain === "states" ? target.role : `${target.role} · ${target.state}`) : "\u00a0"}
        </div>

        {arrived ? (
          <div style={S.row}>
            <div style={{ ...S.feedback, flex: 1, color: C.amber }}>{score.total} guesses from {journeyStart}.</div>
            <button className="abz-btn" style={S.primary} onClick={restart}>Ride again</button>
          </div>
        ) : typing ? (
          <div style={S.row}>
            <input
              ref={inputRef}
              className="abz-input"
              type="text"
              name="answer"
              autoComplete="off"
              data-1p-ignore
              data-lpignore="true"
              style={{ ...S.input, borderColor: lastAnswer ? (lastAnswer.correct ? C.green : C.red) : "#2a3241" }}
              placeholder={`Name the marked ${noun}`}
              value={typed}
              autoCapitalize="words"
              autoCorrect="off"
              onChange={(e) => setTyped(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && submitTyped()}
            />
            <button className="abz-btn" style={S.primary} onClick={submitTyped}>Check</button>
          </div>
        ) : (
          target &&
          domain === "states" &&
          STATE_SMALL.has(target.id) && (
            <div style={{ ...S.hint, textAlign: "left" }}>This one's small on the map — zoom in before you commit.</div>
          )
        )}

        <LastAnswerCard last={lastAnswer} />
      </div>
    </div>
  );
}

function LastAnswerCard({ last }) {
  if (!last) return <div style={S.card}><div style={S.cardPlaceholder}>Your last guess will show up here.</div></div>;
  const color = last.correct ? C.green : C.red;
  return (
    <div style={{ ...S.card, borderLeftColor: color }}>
      <div style={S.cardTop}>
        <span style={S.cardName}>{last.n}</span>
        <span style={{ ...S.cardVerdict, color }}>{last.correct ? "Correct" : "Missed"}</span>
      </div>
      <div style={S.cardMeta}>
        {last.domain === "states" ? <>{last.role} · capital {last.secondary} · pop. {last.pop}</> : <>{last.role} of {last.secondary} · pop. {last.pop}</>}
      </div>
      {last.guessText !== undefined && !last.correct && <div style={S.cardGuess}>You wrote “{last.guessText}.”</div>}
      {last.guessId !== undefined && !last.correct && last.guessId && (
        <div style={S.cardGuess}>You tapped {STATE_BY_ID[last.guessId].name}.</div>
      )}
      <div style={S.cardBlurb}>{last.b}</div>
    </div>
  );
}

function Progress({ count, total, km, frac, score, legs }) {
  return (
    <div>
      <div style={S.scoreRow}>
        <span style={S.scoreMain}>{km.toLocaleString()} km<span style={{ color: C.muted, fontSize: 12 }}> / {TOTAL_KM.toLocaleString()}</span></span>
        <span style={S.scoreMuted}>{count}/{total} · {score.total} guesses</span>
      </div>
      <div style={S.trackOuter}>
        <div style={{ ...S.trackFill, width: `${frac * 100}%` }} />
        {legs.slice(1, -1).map((l, i) => <div key={l.name + i} style={{ ...S.tick, left: `${l.at * 100}%` }} />)}
      </div>
      <div style={S.campLabel}>{legFor(frac, legs)}</div>
    </div>
  );
}

function ScoreRow({ score }) {
  const pct = score.total ? Math.round((score.correct / score.total) * 100) : 0;
  return (
    <div style={S.scoreRow}>
      <span style={S.scoreMain}>{score.correct}/{score.total}</span>
      <span style={S.scoreMuted}>{score.total ? pct + "%" : "—"}</span>
    </div>
  );
}

function ModeButton({ label, active, onClick }) {
  return (
    <button className="abz-btn" onClick={onClick} style={{ ...S.modeBtn, backgroundColor: active ? C.amber : "transparent", color: active ? "#12161f" : C.muted, borderColor: active ? C.amber : "#2a3241" }}>
      {label}
    </button>
  );
}

function SegButton({ label, active, onClick }) {
  return (
    <button className="abz-btn" onClick={onClick} style={{ ...S.segBtn, background: active ? "#2a3241" : "transparent", color: active ? C.cream : C.muted }}>
      {label}
    </button>
  );
}

function Toggle({ on, onClick, label }) {
  return (
    <button className="abz-btn" onClick={onClick} aria-pressed={on} style={{ ...S.toggleBtn, color: on ? "#c9d2e4" : "#8b93a7", borderColor: on ? "#5a6579" : "#2a3241" }}>
      <span style={{ ...S.toggleDot, background: on ? C.border : "transparent" }} />
      {label}
    </button>
  );
}

/* ---------------- shell ---------------- */

export default function AtlasDrillBrazil() {
  const [domain, setDomain] = useState("cities");
  const [input, setInput] = useState("type");
  const [session, setSession] = useState("practice");
  const [scope, setScope] = useState("all");
  const [popTier, setPopTier] = useState("all");
  const [borders, setBorders] = useState(true);
  const [elevation, setElevation] = useState(true);
  const [hints, setHints] = useState(false);

  const pool = domain === "cities" ? topByPopulation(POOLS[scope], POP_TIERS[popTier].frac) : STATE_POOL;

  return (
    <div className="abz-page" style={S.page}>
      <style>{CSS}</style>

      <div style={S.header}>
        <div style={S.eyebrow}>ATLAS DRILL</div>
        <h1 style={S.title}>Brazilian {domain === "states" ? "States" : "Cities"} · {pool.length}</h1>
        <div style={S.sub}>
          {domain === "states" ? "every state and the Federal District — one shape each" : SCOPE_BLURB[scope]}
          {domain === "cities" && popTier !== "all" && ` — ${POP_TIERS[popTier].label.toLowerCase()} by population`}
        </div>
      </div>

      <div style={S.modeRow}>
        <ModeButton label="States" active={domain === "states"} onClick={() => setDomain("states")} />
        <ModeButton label="Cities" active={domain === "cities"} onClick={() => setDomain("cities")} />
      </div>
      <div style={S.modeRow}>
        <ModeButton label="Name it" active={input === "type"} onClick={() => setInput("type")} />
        <ModeButton label="Find it" active={input === "tap"} onClick={() => setInput("tap")} />
      </div>

      <div className="abz-panel" style={S.panel}>
        {domain === "cities" && (
          <div style={S.segRow}>
            {Object.entries(SCOPES).map(([k, s]) => <SegButton key={k} label={s.label} active={scope === k} onClick={() => setScope(k)} />)}
          </div>
        )}
        {domain === "cities" && (
          <div style={S.segRow}>
            {Object.entries(POP_TIERS).map(([k, t]) => <SegButton key={k} label={t.label} active={popTier === k} onClick={() => setPopTier(k)} />)}
          </div>
        )}
        <div style={S.segRow}>
          <SegButton label="Practice" active={session === "practice"} onClick={() => setSession("practice")} />
          <SegButton label={JOURNEY_LABEL[domain]} active={session === "journey"} onClick={() => setSession("journey")} />
        </div>

        <Quiz key={domain + session + scope + popTier} domain={domain} pool={pool} input={input} session={session} borders={borders} elevation={elevation} hints={hints} />

        <div style={S.toggleRow}>
          <Toggle on={borders} onClick={() => setBorders((b) => !b)} label={"Borders " + (borders ? "on" : "off")} />
          <Toggle on={elevation} onClick={() => setElevation((e) => !e)} label={"Elevation " + (elevation ? "on" : "off")} />
          <Toggle on={hints} onClick={() => setHints((h) => !h)} label={"Hints " + (hints ? "on" : "off")} />
        </div>
      </div>
    </div>
  );
}

const S = {
  page: { minHeight: "100vh", background: C.page, color: "#eef1f6", fontFamily: SANS, display: "flex", flexDirection: "column", alignItems: "center" },
  header: { textAlign: "center", marginBottom: 14 },
  eyebrow: { fontFamily: MONO, fontSize: 11, letterSpacing: ".18em", color: C.muted, marginBottom: 4 },
  title: { fontFamily: SERIF, fontSize: 27, fontWeight: 700, margin: 0, color: C.cream },
  sub: { fontSize: 12, color: C.muted, marginTop: 5 },
  modeRow: { display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap", justifyContent: "center" },
  toggleRow: { display: "flex", gap: 8, justifyContent: "center", flexWrap: "wrap", marginTop: 2 },
  toggleBtn: { display: "inline-flex", alignItems: "center", gap: 7, background: "transparent", border: "1px solid #2a3241", borderRadius: 999, padding: "6px 14px", fontSize: 12.5, fontWeight: 600 },
  toggleDot: { width: 8, height: 8, borderRadius: 999, border: "1px solid #5a6579", display: "inline-block" },
  segRow: { display: "flex", gap: 4, padding: 4, borderRadius: 10, background: C.ocean, border: "1px solid #262e3d" },
  segBtn: { flex: 1, border: "none", borderRadius: 7, padding: "7px 0", fontSize: 13, fontWeight: 600 },
  trackOuter: { position: "relative", height: 8, marginTop: 8, borderRadius: 999, background: C.ocean, border: "1px solid #2a3241", overflow: "hidden" },
  trackFill: { position: "absolute", left: 0, top: 0, bottom: 0, background: "linear-gradient(90deg,#8a6a2f,#e3a542)", transition: "width .45s cubic-bezier(.22,1,.36,1)" },
  tick: { position: "absolute", top: 0, bottom: 0, width: 1, background: "#2a3241" },
  campLabel: { marginTop: 6, fontFamily: MONO, fontSize: 11, letterSpacing: ".1em", color: C.muted, textTransform: "uppercase" },
  modeBtn: { border: "1px solid #2a3241", borderRadius: 999, padding: "8px 20px", fontSize: 14, fontWeight: 600, background: "transparent" },
  panel: { width: "100%", background: C.panel, border: "1px solid #262e3d", display: "flex", flexDirection: "column", gap: 11 },
  scoreRow: { display: "flex", justifyContent: "space-between", alignItems: "baseline" },
  scoreMain: { fontFamily: MONO, fontSize: 15, color: C.amber },
  scoreMuted: { fontFamily: MONO, fontSize: 13, color: C.muted },
  mapWrap: { position: "relative", overflow: "hidden", border: "1px solid #262e3d" },
  svg: { width: "100%", height: "auto", display: "block", background: C.ocean, cursor: "pointer" },
  compass: { position: "absolute", top: 9, right: 9, opacity: 0.75, pointerEvents: "none" },
  reset: { position: "absolute", bottom: 9, right: 9, background: "rgba(12,18,25,.85)", color: "#eef1f6", border: "1px solid #3a4258", borderRadius: 8, padding: "6px 10px", fontSize: 12 },
  prompt: { fontFamily: SERIF, fontSize: 18, textAlign: "center" },
  subPrompt: { textAlign: "center", fontFamily: MONO, fontSize: 11, letterSpacing: ".08em", color: C.muted, marginTop: -6 },
  hint: { textAlign: "center", fontSize: 12, color: C.muted, lineHeight: 1.45 },
  card: { background: C.ocean, border: "1px solid #262e3d", borderLeft: "3px solid #2a3241", borderRadius: 10, padding: "11px 13px", display: "flex", flexDirection: "column", gap: 4 },
  cardPlaceholder: { fontSize: 12.5, color: "#5a6579", fontStyle: "italic" },
  cardTop: { display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 },
  cardName: { fontFamily: SERIF, fontSize: 15.5, color: C.cream, fontWeight: 700 },
  cardVerdict: { fontFamily: MONO, fontSize: 11, letterSpacing: ".06em", textTransform: "uppercase", fontWeight: 700, whiteSpace: "nowrap" },
  cardMeta: { fontFamily: MONO, fontSize: 11.5, color: C.muted },
  cardGuess: { fontSize: 12.5, color: "#c9d2e4" },
  cardBlurb: { fontSize: 13, color: "#c9d2e4", lineHeight: 1.5, marginTop: 3 },
  row: { display: "flex", gap: 8, alignItems: "center" },
  input: { flex: 1, minWidth: 0, background: C.ocean, border: "1px solid #2a3241", borderRadius: 8, padding: "11px 12px", fontSize: 16, color: "#eef1f6" },
  primary: { background: C.amber, color: "#12161f", border: "none", borderRadius: 8, padding: "11px 16px", fontSize: 14, fontWeight: 700, whiteSpace: "nowrap" },
  feedback: { fontSize: 14, fontWeight: 600, animation: "abz-pop .2s ease" },
};

const CSS = `
@keyframes abz-pop { from { transform: scale(0.9); opacity: 0 } to { transform: scale(1); opacity: 1 } }
@keyframes abz-ping { 0% { transform: scale(.55); opacity: .95 } 100% { transform: scale(1.9); opacity: 0 } }
.abz-ping { transform-box: fill-box; transform-origin: center; animation: abz-ping 1.7s ease-out infinite; }
.abz-btn { transition: background-color .15s, border-color .15s, transform .1s; cursor: pointer; }
.abz-btn:active { transform: scale(.97); }
.abz-btn:focus-visible, .abz-input:focus-visible { outline: 2px solid ${C.amber}; outline-offset: 2px; }
.abz-input:focus { outline: none; border-color: ${C.amber} !important; }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; } }

.abz-page { padding: 20px 14px 40px; }
.abz-panel { max-width: 460px; padding: 14px; border-radius: 16px; }
.abz-map { border-radius: 12px; }
.abz-layout { display: flex; flex-direction: column; gap: 14px; }
.abz-side { display: flex; flex-direction: column; gap: 10px; min-width: 0; }

@media (max-width: 560px) {
  .abz-page { padding: 14px 0 28px; }
  .abz-panel { max-width: 100%; padding: 12px 12px 16px; border-radius: 0; border-left: none; border-right: none; }
  .abz-map { margin-left: -12px; margin-right: -12px; width: calc(100% + 24px); border-radius: 0; border-left: none; border-right: none; }
}
@media (min-width: 900px) {
  .abz-panel { max-width: 980px; }
  .abz-layout { flex-direction: row; align-items: flex-start; gap: 22px; }
  .abz-map { flex: 0 0 560px; width: 560px; }
  .abz-side { flex: 1 1 320px; min-width: 300px; padding-top: 2px; }
}
`;
